    art = d.get("signal_artifact") or {}
    has_art = bool(art.get("data_b64")) if isinstance(art, dict) else False
    cur = seen.get(fid)
    if cur is None:
        seen[fid] = (f, d, has_art)
    elif has_art and not cur[2]:
