# recency: correlation on last 252 rows
print("\nPairwise |corr| last-252d:")
C2 = np.full((n, n), np.nan)
for i in range(n):
    for j in range(n):
        a = panels[fids[i]][-252:]; b = panels[fids[j]][-252:]
