import json, glob, os, re

files = sorted(glob.glob('factors/*.json'))
files = [f for f in files if not f.endswith('.bak')]

# Keep canonical: file with no timestamp pattern
def is_ts(b):
    return bool(re.search(r'\.\d{8}T\d{9}\.json$', b))

canon = {}
for f in files:
    b = os.path.basename(f)
    if is_ts(b):
        continue
    d = json.load(open(f))
    fid = d.get('factor_id')
    canon[fid] = f

print("Unique factor_ids (canonical files):", len(canon))
for fid, f in sorted(canon.items()):
    d = json.load(open(f))
    val = d.get('validation', {})
    adm = d.get('benchmark_admission', {})
    sel = adm.get('selected_metrics', {}) or {}
    m = val.get('metrics', {}) or {}
    by_year = val.get('by_year_ic1', {}) or {}
    tags = d.get('tags', [])
    tags_s = ','.join(tags) if isinstance(tags, list) else str(tags)
    yr_ic = {y: round(v.get('ic', float('nan')), 4) for y, v in by_year.items()}
    print(f"ID={fid}")
    print(f"  NAME={d.get('factor_name')}")
    print(f"  TAGS={tags_s}")
    print(f"  STATUS={val.get('status')} | selected ic={sel.get('ic')} icir={sel.get('icir')} (year={sel.get('metric_path','').split('.')[-1] if sel.get('metric_path') else '?'})")
    print(f"  metrics ic1={m.get('ic1')} icir1={m.get('icir1')} ic5={m.get('ic5')} ic10={m.get('ic10')} turnover10d={m.get('turnover_10d')} hit1={m.get('hit1')}")
    print(f"  by_year_ic={yr_ic}")
    rn = val.get('regime_notes', {})
    if isinstance(rn, dict):
        rn_s = {k: (str(v)[:80] if not isinstance(v, (int, float)) else v) for k, v in rn.items()}
        print(f"  regime_notes={rn_s}")
    print()
