    v = d.get('validation', {})
    # try to find scalar metrics in nested dicts
    def find_scalars(obj, prefix='', depth=0):
        res = {}
        if depth>3: return res
        if isinstance(obj, dict):
            for k,val in obj.items():
                if isinstance(val,(int,float)) and not isinstance(val,bool):
                    res[prefix+k]=val
                elif isinstance(val,dict):
                    res.update(find_scalars(val, prefix+k+'.', depth+1))
