import pandas as pd, numpy as np, glob, os, json

cut = pd.Timestamp("2030-04-25")
SYMS = ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']

def load(sym):
    df=pd.read_csv(f"../persistent/stock_data/{sym}.csv")
    df.columns=[c.strip() for c in df.columns]
    dc=[c for c in df.columns if c.lower() in ("date","datetime","time")][0]
    df[dc]=pd.to_datetime(df[dc])
    df=df.sort_values(dc).reset_index(drop=True)
    df=df[df[dc]<=cut].reset_index(drop=True)
    df=df.rename(columns={dc:"date"})
    for c in ["open","high","low","close"]:
        if c in df.columns: df[c]=pd.to_numeric(df[c],errors="coerce")
    return df

# Build aligned panel
panel={}
for s in SYMS:
    df=load(s)
    panel[s]={"date":df["date"].values,"open":df["open"].values,"high":df["high"].values,
              "low":df["low"].values,"close":df["close"].values}
# Use SPX dates as master calendar
master=pd.to_datetime(panel["SPX"]["date"])
def series(sym,field):
    d=panel[sym]
    dd=pd.to_datetime(d["date"])
    s=pd.Series(d[field],index=dd)
    return s.reindex(master)

close=pd.DataFrame({s:series(s,"close") for s in SYMS})
open_=pd.DataFrame({s:series(s,"open") for s in SYMS})
high=pd.DataFrame({s:series(s,"high") for s in SYMS})
low=pd.DataFrame({s:series(s,"low") for s in SYMS})

# VIX
vixdf=pd.read_csv("../persistent/index_data/VIX.csv")
vixdf.columns=[c.strip() for c in vixdf.columns]
vixdf["date"]=pd.to_datetime(vixdf["date"])
vixdf=vixdf[vixdf["date"]<=cut].sort_values("date")
vix=vixdf.set_index("date")["close"].reindex(master)

# flatness check
for s in ["HSI","CN10Y"]:
    c=close[s].dropna()
    nflat=(c.diff()==0).sum()
    print(f"{s}: last {len(c)} obs, flat days in last 60:", int((c.diff()==0).tail(60).sum()), "| first flat idx in tail window:", c.index[-60:][c.diff().tail(60)==0][:1])

# Factor computations
def nclv(nd):
    return -(close - low.rolling(nd).min())/(high.rolling(nd).max()-low.rolling(nd).min())
def rev(nd):
    return -(np.log(close)-np.log(close.shift(nd)))
def rev_vs():
    r=close.pct_change()
    return -(np.log(close)-np.log(close.shift(1)))/r.rolling(20).std()
def id_rev():
    return -(close/open_-1)
def nbody():
    return -(close-open_)/(high-low)
def mom120():
    return close.shift(5)/close.shift(125)-1
def vix_beta():
    r=close.pct_change()
    vret=vix.pct_change()
    beta= r.rolling(60).cov(vret)/vret.rolling(60).var()
    return -beta*(vix/vix.shift(20)-1)
def vov():
    return close.pct_change().rolling(20).std().rolling(60).std()

factors={
 "miner2_20260715_nclv_1d": nclv(1),
 "miner2_20260715_nclv_2d": nclv(2),
 "miner2_20260715_nclv_3d": nclv(3),
 "miner2_20260715_nclv_5d": nclv(5),
 "miner2_20260715_rev_1d": rev(1),
 "miner2_20260715_rev_1d_vs": rev_vs(),
 "miner2_20260715_rev_2d": rev(2),
 "miner2_20260715_rev_3d": rev(3),
 "miner2_20260715_rev_5d": rev(5),
 "miner2_20260715_id_rev_1d": id_rev(),
 "miner2_20260715_nbody_1d": nbody(),
 "mom_120d_skip5": mom120(),
 "vix_beta_cond_60x20": vix_beta(),
 "vol_of_vol20x60": vov(),
}
# save for reuse
out={k:v.copy() for k,v in factors.items()}
np.savez("_screener_factors.npz", **{k:v.values for k,v in out.items()})
import pickle
with open("_screener_dates.pkl","wb") as f: pickle.dump(master,f)

# IC computation
ret1=close.pct_change().shift(-1)  # next-day return
ret5=close.pct_change(5).shift(-5)
ret10=close.pct_change(10).shift(-10)

def ic_stats(fv, fwd, win=60):
    ics=[]
    for i in range(len(master)-1):
        t=master[i]
        x=fv.iloc[i]
        y=fwd.iloc[i]
        m=pd.concat([x,y],axis=1).dropna()
        if len(m)<6: continue
        ic=m.iloc[:,0].rank().corr(m.iloc[:,1].rank())
        if pd.notna(ic): ics.append((t,ic))
    df=pd.DataFrame(ics,columns=["date","ic"]).set_index("date")
    recent=df.tail(win)
    return {"ic_mean": float(recent["ic"].mean()), "icir": float(recent["ic"].mean()/recent["ic"].std()) if recent["ic"].std()>0 else 0.0,
            "hit": float((recent["ic"]>0).mean()), "n": int(len(recent)), "ic_mean_120": float(df["ic"].tail(120).mean())}

print("\n=== Recent IC (last 60 trading days through 2030-04-25, rank IC vs 1d fwd) ===")
res={}
for fid,fv in factors.items():
    s1=ic_stats(fv,ret1,60)
    s5=ic_stats(fv,ret5,60)
    s10=ic_stats(fv,ret10,60)
    res[fid]={"ic1":s1,"ic5":s5,"ic10":s10}
    print(f"{fid:32s} ic1={s1['ic_mean']:+.4f} icir1={s1['icir']:+.3f} hit1={s1['hit']:.2f} n={s1['n']} | ic5={s5['ic_mean']:+.4f} ic10={s10['ic_mean']:+.4f} | ic1_120={s1['ic_mean_120']:+.4f}")
with open("_screener_ic.json","w") as f: json.dump(res,f,indent=1,default=str)
