active = ['rev_1d','rev_2d','rev_3d','rev_5d','nclv_1d','nclv_2d','nclv_3d','nclv_5d','id_rev_1d','nbody_1d','rev_1d_vs','mom_120d_skip5','vol_of_vol20x60','vix_beta_cond_60x20']
